commands.command:
sudo /bin/sh -c "cat > /tmp/branch_stock_privileges.sql <<'BRANCH_STOCK_SQL'
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app;
GRANT CONNECT ON DATABASE branch_stock TO auditor;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app;
GRANT USAGE ON SCHEMA public TO auditor;
REVOKE ALL ON stock FROM PUBLIC;
REVOKE ALL ON supplier_costs FROM PUBLIC;
GRANT SELECT, UPDATE ON stock TO stock_app;
GRANT SELECT ON stock, supplier_costs TO auditor;
CREATE FUNCTION enforce_stock_quantity_only() RETURNS trigger AS \$\$
BEGIN
  IF session_user = 'stock_app' AND NEW.sku <> OLD.sku THEN
    RAISE EXCEPTION 'stock_app may update quantity only';
  END IF;
  RETURN NEW;
END;
\$\$ LANGUAGE plpgsql;
CREATE TRIGGER stock_quantity_only BEFORE UPDATE ON stock FOR EACH ROW EXECUTE PROCEDURE enforce_stock_quantity_only();
BRANCH_STOCK_SQL
"; sudo -u postgres /usr/bin/psql -v ON_ERROR_STOP=1 -d branch_stock -f /tmp/branch_stock_privileges.sql; rc=$?; sudo rm -f /tmp/branch_stock_privileges.sql; exit $rc

sudo /bin/sh -c "cat > /tmp/branch_stock_privileges.sql <<'BRANCH_STOCK_SQL'
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app;
GRANT USAGE ON SCHEMA public TO auditor;
REVOKE ALL ON stock FROM PUBLIC;
REVOKE ALL ON supplier_costs FROM PUBLIC;
GRANT SELECT, UPDATE ON stock TO stock_app;
GRANT SELECT ON stock, supplier_costs TO auditor;
CREATE FUNCTION enforce_stock_quantity_only() RETURNS trigger AS \$\$
BEGIN
  IF session_user = 'stock_app' AND NEW.sku <> OLD.sku THEN
    RAISE EXCEPTION 'stock_app may update quantity only';
  END IF;
  RETURN NEW;
END;
\$\$ LANGUAGE plpgsql;
CREATE TRIGGER stock_quantity_only BEFORE UPDATE ON stock FOR EACH ROW EXECUTE PROCEDURE enforce_stock_quantity_only();
BRANCH_STOCK_SQL
"; sudo -u postgres /usr/bin/psql -v ON_ERROR_STOP=1 -d branch_stock -f /tmp/branch_stock_privileges.sql; rc=$?; sudo rm -f /tmp/branch_stock_privileges.sql; exit $rc

sudo /bin/sh -c "cat > /tmp/branch_stock_catalog.sql <<'CATALOG_SQL'
SELECT 'ROLE', rolname, CASE WHEN rolsuper THEN 'super' ELSE 'nosuper' END, CASE WHEN rolcreatedb THEN 'createdb' ELSE 'nocreatedb' END, CASE WHEN rolcreaterole THEN 'createrole' ELSE 'nocreaterole' END, CASE WHEN rolcanlogin THEN 'login' ELSE 'nologin' END FROM pg_roles WHERE rolname IN ('stock_app','auditor') ORDER BY rolname;
SELECT 'TABLE_ACL', relname, pg_get_userbyid(relowner), relacl FROM pg_class WHERE relname IN ('stock','supplier_costs') ORDER BY relname;
SELECT 'SCHEMA_ACL', nspname, nspacl FROM pg_namespace WHERE nspname='public';
SELECT 'TRIGGER', tgname, CASE WHEN tgenabled THEN 'enabled' ELSE 'disabled' END FROM pg_trigger WHERE tgname='stock_quantity_only';
CATALOG_SQL
"; sudo -u postgres /usr/bin/psql -d branch_stock -F '|' -Atf /tmp/branch_stock_catalog.sql; rc=$?; sudo rm -f /tmp/branch_stock_catalog.sql; exit $rc

